import{at as e,it as t,n,vt as r}from"./chunks/framework.yntlMcNk.js";var i=JSON.parse(`{"title":"Portal","description":"","frontmatter":{"title":"Portal"},"headers":[],"relativePath":"de/api/reference/portal.md","filePath":"de/api/reference/portal.md"}`),a={name:`de/api/reference/portal.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="portal" tabindex="-1">Portal <a class="header-anchor" href="#portal" aria-label="Permalink to “Portal”">​</a></h1><div><p>Operationen des Tags <strong>Portal</strong>, die dieses Release implementiert. Erzeugt aus <code>api/openapi.yaml</code>; geplante Operationen sind nicht aufgeführt. Die Beschreibungen stammen aus dem englischen API-Vertrag.</p><h2 id="listPortalCatalogs" tabindex="-1">Shared catalogs of the portal (SCR-050) <a class="header-anchor" href="#listPortalCatalogs" aria-label="Permalink to “Shared catalogs of the portal (SCR-050)”">​</a></h2><p><code>GET /portal/catalogs</code> · <code>listPortalCatalogs</code></p><p>The catalogs with scope <code>instance</code>, ordered by name (case-insensitive). Personal catalogs never appear in the portal, not even the caller&#39;s own.</p><p><strong>Zugriff</strong>: Berechtigung <code>portal:read</code></p><h3 id="antworten" tabindex="-1">Antworten <a class="header-anchor" href="#antworten" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>200</td><td>Shared catalogs</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code> and <code>POST /me/password/suggestion</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="queryPortalCatalog" tabindex="-1">Query a shared catalog read-only (SCR-050) <a class="header-anchor" href="#queryPortalCatalog" aria-label="Permalink to “Query a shared catalog read-only (SCR-050)”">​</a></h2><p><code>GET /portal/catalogs/{id}/query</code> · <code>queryPortalCatalog</code></p><p>One page of rows of a catalog with scope <code>instance</code>, with the catalog&#39;s configured columns, default sort and default join mode. The result equals that of the catalog query (<code>queryCatalog</code>) without filters, join mode overrides or view, including its visibility rules: only properties with visibility <code>public</code> appear (REQ-124, REQ-160) and soft-deleted entities are not returned. <code>page</code>, <code>pageSize</code> and <code>sort</code> behave as in the catalog query. A personal catalog is answered with 404, like a catalog that does not exist, also for its creator.</p><p><strong>Zugriff</strong>: Berechtigung <code>portal:read</code></p><h3 id="parameter" tabindex="-1">Parameter <a class="header-anchor" href="#parameter" aria-label="Permalink to “Parameter”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Ort</th><th>Pflicht</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>ja</td><td>string (uuid)</td><td>–</td></tr><tr><td><code>page</code></td><td>query</td><td>nein</td><td>integer</td><td>–</td></tr><tr><td><code>pageSize</code></td><td>query</td><td>nein</td><td>integer</td><td>–</td></tr><tr><td><code>sort</code></td><td>query</td><td>nein</td><td>string</td><td><code>{field}:{asc|desc}</code>, multiple comma-separated</td></tr></tbody></table><h3 id="antworten-1" tabindex="-1">Antworten <a class="header-anchor" href="#antworten-1" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>200</td><td>One page of catalog rows</td><td>–</td></tr><tr><td>400</td><td>Invalid paging or sort parameters (problem type <code>urn:oea:problem:validation-failed</code>), e.g. an unknown sort column or a page size above 200; <code>invalidFields</code> names the rejected parameters.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code> and <code>POST /me/password/suggestion</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Resource not found, or an existence-sensitive resource the caller may not see (same response for both cases, REQ-159)</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};